import{_ as l,a0 as p,w as o,s as n,ao as u,I as s,x as t,a1 as r,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const U=JSON.parse('{"title":"树莓派 4 来袭！ | LCTT x X-CMD","titleTemplate":false,"description":"树莓派 4 来袭！ | LCTT (201906) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"树莓派 4 来袭！ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"树莓派 4 来袭！ | LCTT (201906) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201906/20190624 Raspberry Pi 4 is here","title":"树莓派 4 来袭！","tag":"201906","desc":""},"relativePath":"201906/20190624 Raspberry Pi 4 is here.md","filePath":"[post].md"}'),b={name:"201906/20190624 Raspberry Pi 4 is here.md"};function d(m,e,f,B,h,P){const i=p("Link");return o(),n("div",null,[e[15]||(e[15]=u('<h1 id="树莓派-4-来袭" tabindex="-1">树莓派 4 来袭！ <a class="header-anchor" href="#树莓派-4-来袭" aria-label="Permalink to “树莓派 4 来袭！”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/201906/29/161918icu6zrn8qrg3p38u.png" alt=""></p><blockquote><p>售价 35 美元起的新一代树莓派单板计算机，装载了 1.5 GHz 的 Arm 芯片，并支持双 HDMI 4K 显示，全吞吐量千兆以太网，以及更多新特性。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/raspberry-pi-4_lead.jpg?itok=2bkk43om" alt="Raspberry Pi 4 board" title="Raspberry Pi 4 board"></p><p>树莓派的最新版本树莓派 4 代，已于近日（北京时间 6 月 24 日）发布，这早于此前预期。树莓派 4 装载了 1.5 GHz 的 Arm 芯片和 VideoCore GPU，支持双 4K 显示输出，并引入了 USB 3 接口和全吞吐量千兆以太网，以及最高可达 4G 的多个可选 RAM 配置。</p><p><img src="https://opensource.com/sites/default/files/uploads/raspberry-pi-4-case.jpg" alt="Raspberry Pi 4 case" title="Raspberry Pi 4 case"></p><p>树莓派 4 是非常强大的单板计算机，其起始售价依然是 35 美元。起始版的 RAM 配置为 1G，2G RAM 配置的树莓派售价为 45 美元，顶配 4G RAM 的树莓派售价为 55 美元，采用这种差异化定价对树莓派尚属首次。</p><p>树莓派 4 的详细配置如下：</p><ul><li>1.5 GHz 4 核心 64 位博通 BCM2711 A72 CPU</li><li>VideoCore VI GPU</li><li>千兆以太网端口</li><li>1GB/2GB/4GB LPDDR4 SDRAM 内存</li><li>双 Micro-HDMI 接口</li><li>两个 USB 3 接口</li><li>两个 USB 2 接口</li><li>双频（2.4 GHz 和 5 GHz）无线网络</li><li>蓝牙 5.0</li><li>USB Type C 电源接口</li><li>CSI 摄像头接口</li><li>DSI 显示接口</li><li>MicroSD 卡槽</li><li>PoE（以太网供电）供电针</li><li>完全兼容早期的树莓派产品</li></ul><h3 id="usb-接口和网络" tabindex="-1">USB 接口和网络 <a class="header-anchor" href="#usb-接口和网络" aria-label="Permalink to “USB 接口和网络”">​</a></h3><p>树莓派 4 板载了更高速率的 USB 3 接口；它通过 Type C 接口供电，并提供两个 USB 3 接口和两个 USB 2 接口。USB 3 接口可以为连接的硬盘和其它外部设备提供更高的速率。</p><p><img src="https://opensource.com/sites/default/files/uploads/raspberry-pi-4-usb.jpg" alt="Raspberry Pi 4 USBs" title="Raspberry Pi 4 USBs"></p><p>基于 BCM2835 的树莓派 1 到 3 代的芯片只有一个本地 USB 接口，并且没有以太网接口，因而需要使用板子的 USB 集线器给出更多的 USB 接口和以太网接口。树莓派 3B+ 增加了一个专用的局域网（LAN）芯片，装载了千兆以太网，但它受到 USB 2 速率的限制。树莓派 4 板载了专门的千兆以太网，并且由于它不再受到 USB 速率的限制，网络速度要快得多。</p><p>树莓派 4 采用了 3B+ 中已有的技术 —— 该技术使得树莓派 3B+ 成为了第一个带有双频无线网络的单板计算机，即可以同时连接 2.4 GHz 和 5 GHz 频率的网络。</p><h3 id="显示" tabindex="-1">显示 <a class="header-anchor" href="#显示" aria-label="Permalink to “显示”">​</a></h3><p>设计第一代树莓派时，其 CPU 和 GPU 性能的平衡大大偏向于 GPU。VideoCore IV 是一个非常强大的图形处理器，支持全高清 1080p 多媒体的处理，这就是为什么树莓派一直作为家庭媒体中心而广受欢迎的原因。树莓派 2 代在某种程度上进行了权衡修改，并将 CPU 的性能进行提升，将树莓派从单核发展成四核 ARM 芯片。而树莓派 4 代将 CPU 和 GPU 的性能都进行了大幅提升。新的 VideoCore VI GPU 支持 4K 视频，并允许通过板子上的两个 Micro HDMI 端口（板子特意保持了和旧有型号相同的尺寸）进行双显示输出，这里要用一个适配器或 Micro HDMI 转 full HDMI 的转换线连接到 HDMI 屏幕。</p><p>当你需要同时浏览多个窗口时，需要用到更多的物理显示屏，双显示的好处在此时就得到了绝佳体现。如果你正在编程，你可能会在其中一个屏幕上编写代码，构建网站或应用，而在另一个屏幕上查看数据库、Web 浏览器、电子邮件或其他内容。这是树莓派首次可以不必将开发局限在一台显示器上，从而可以让你在需要时，在不同的屏幕上构建具有不同内容的基于树莓派的项目。</p><p>该树莓派还有一个显示器串行接口（DSI)，用于驱动另一个特殊的显示-这里并非指另一个监视器本身，而是通过一根挠性电缆连接的官方树莓派触摸屏显示器。</p><h3 id="raspbian-buster" tabindex="-1">Raspbian Buster <a class="header-anchor" href="#raspbian-buster" aria-label="Permalink to “Raspbian Buster”">​</a></h3><p>树莓派 4 发布后，紧接着更新了基于 Debian 的系统 Raspbian Buster，而新的树莓派对 OpenGL ES 3 的支持，使我们在 Raspbian Buster 上为树莓派 4 开发任意软件成为可能。Buster 对界面进行了一些调整，并对很多软件进行了升级，其中包括 Python3.7。</p><p><img src="https://opensource.com/sites/default/files/uploads/raspbian-buster.png" alt="Raspbian Buster" title="Raspbian Buster"></p><h3 id="开源图形驱动程序" tabindex="-1">开源图形驱动程序 <a class="header-anchor" href="#开源图形驱动程序" aria-label="Permalink to “开源图形驱动程序”">​</a></h3><p>在过去的五年中，Eric Anholt 一直致力于为树莓派编写开源图形驱动程序。现在，Raspbian 可以使用这个驱动程序加速树莓派上的 Web 浏览、桌面图形和 3D 应用，这取代了以前需要的大量闭源代码。非常感谢 Eric 和博通的贡献。</p><p>按之前预计，树莓派 4 将于明年完成，但由于芯片设计比预期更早投入生产，树莓派 4 因而可以提早到现在发布。</p><hr><p>树莓派 4 已经开始发售，你会选择哪个型号呢？在评论中说出你的想法吧。</p><hr>',27)),s("p",null,[e[1]||(e[1]=t("via: ",-1)),r(i,{href:"https://opensource.com/article/19/6/raspberry-pi-4"},{default:a(()=>[...e[0]||(e[0]=[t("https://opensource.com/article/19/6/raspberry-pi-4",-1)])]),_:1})]),s("p",null,[e[6]||(e[6]=t("作者：",-1)),r(i,{href:"https://opensource.com/users/bennuttall"},{default:a(()=>[...e[2]||(e[2]=[t("Ben Nuttall",-1)])]),_:1}),e[7]||(e[7]=t(" 选题：",-1)),r(i,{href:"https://github.com/lujun9972"},{default:a(()=>[...e[3]||(e[3]=[t("lujun9972",-1)])]),_:1}),e[8]||(e[8]=t(" 译者：",-1)),r(i,{href:"https://github.com/wahailin"},{default:a(()=>[...e[4]||(e[4]=[t("wahailin",-1)])]),_:1}),e[9]||(e[9]=t(" 校对：",-1)),r(i,{href:"https://github.com/wxy"},{default:a(()=>[...e[5]||(e[5]=[t("wxy",-1)])]),_:1})]),s("p",null,[e[12]||(e[12]=t("本文由 ",-1)),r(i,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[10]||(e[10]=[t("LCTT",-1)])]),_:1}),e[13]||(e[13]=t(" 原创编译，",-1)),r(i,{href:"https://linux.cn/"},{default:a(()=>[...e[11]||(e[11]=[t("Linux中国",-1)])]),_:1}),e[14]||(e[14]=t(" 荣誉推出",-1))])])}const R=l(b,[["render",d]]);export{U as __pageData,R as default};
